mapper.select:
/*selectMasterMdCmCmsBuyInfoList*/ SELECT P.CMS_CATLG_ID || '-' || LPAD(P.CATLG_SEQ, 5, '0') AS TCODE /* 행 유니크 키 (상세 팝업 호출용, hidden) */ /* -- 밴드1 : 식별 · 상태 -- */ ,P.CMS_CATLG_ID /* 상품정보코드 */ ,P.CMS_CATLG_ID || '-' || LPAD(P.CATLG_SEQ, 5, '0') AS BUY_INFO_ID /* 구매정보코드 (키, 화면 hidden) */ ,LPAD(P.CATLG_SEQ, 5, '0') AS BUY_INFO_SEQ /* 구매정보코드 : 화면 표기는 순번만 쓴다(상품정보코드는 옆 열에 있다) */ ,DECODE(P.STATUS, 'D', '불가', '가능') AS SUPPLY_STATUS /* 공급상태 */ /* 만료여부 : 종료일 없으면 공란. 만료예정 기준 30일은 설계서에 정의가 없어 잠정값이다. */ ,CASE WHEN P.BUY_CLOSE_DATE IS NULL OR TRIM(P.BUY_CLOSE_DATE) IS NULL THEN '' WHEN P.BUY_CLOSE_DATE < TO_CHAR(SYSDATE, 'YYYYMMDD') THEN '만료' WHEN P.BUY_CLOSE_DATE <= TO_CHAR(SYSDATE + 30, 'YYYYMMDD') THEN '만료예정' ELSE '' END AS EXPIRE_YN /* 만료여부 */ ,C.DESCRIPTION_LOC /* 품목명 */ ,C.MODEL_INFO /* 모델번호 */ ,C.SPECIFICATION /* 규격 */ ,C.MAKER_NAME /* 제조사 */ ,(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE) AS ORIGIN_CODE_NAME /* 원산지 */ ,C.ORDER_MEASURE /* 단위 */ ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = P.AGENT) AS AGENT_NAME /* 협력사명 */ ,P.AGENT AS AGENT_CODE /* 협력사코드 */ /* -- 밴드2 : 유효기간 · 매핑 · 분류 -- */ ,P.BUY_CLOSE_DATE AS BUY_CLOSE_DATE /* 매입단가 종료일 */ /* 매핑고객사수 = 이 구매정보에 연결된 ICOMCQDT 건수 · 지정고객사수 = 그중 CSV_YN='Y' 매핑 축(CMS_CATLG_ID·CATLG_SEQ)은 ICOMCQDT_12 인덱스가 받는다 — 행당 인덱스 레인지 스캔 2회. */ ,(SELECT COUNT(*) FROM ICOMCQDT Q WHERE Q.CMS_CATLG_ID = P.CMS_CATLG_ID AND Q.CATLG_SEQ = P.CATLG_SEQ) AS MAP_BUYER_CNT /* 매핑고객사수 */ ,(SELECT COUNT(*) FROM ICOMCQDT Q WHERE Q.CMS_CATLG_ID = P.CMS_CATLG_ID AND Q.CATLG_SEQ = P.CATLG_SEQ AND NVL(Q.CSV_YN, 'N') = 'Y') AS DESIG_BUYER_CNT /* 지정고객사수 */ ,DECODE(C.ITEM_GUBUN, 'G', '표준품', '비표준품') AS ITEM_GUBUN_NM /* 상품구분 */ ,DECODE(NVL(C.ONETIME_YN, 'N'), 'Y', '일회성', '일반') AS ONETIME_NM /* 일회성구분 */ ,(SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M181' AND MD.CODE = C.TR_HANDLE_TYPE) AS TR_HANDLE_NM /* TR취급가능여부 */ ,(SELECT SG.SG_NAME FROM CMSCATEG CG, KEPSGMG SG WHERE CG.CMS_CATEG_ID = C.CMS_CATEG_ID AND CG.STATUS <> 'D' AND CG.SG_ID = SG.SG_ID) AS SG_NAME /* 카테고리(=SG) */ ,C.CMS_CATEG_ID /* 상세분류코드 */ ,(SELECT CATEG_NAME FROM CMSCATEG WHERE CMS_CATEG_ID = C.CMS_CATEG_ID AND STATUS <> 'D') AS CMS_CATEG_NAME /* 상세분류 */ ,(SELECT MD.TEXT4 FROM CMSCATEG CG, ICOMCOD3 MD WHERE CG.CMS_CATEG_ID = C.CMS_CATEG_ID AND CG.STATUS <> 'D' AND MD.BUYER = 'KRKORE0001' AND MD.TYPE = 'CMSM' AND MD.CODE2 = '1' AND MD.FLAG = 'Y' AND MD.CODE1 = CG.SG_ID) AS KEP_USER_NAME /* 구매담당자(SG 정담당) */ /* -- 밴드3 : 기준가 · 이력 -- */ ,C.BASE_PRICE /* 기준가(상품 단위) */ /* 기준가매익율 : 기준가가 없거나 0이면 나눗셈이 성립하지 않아 공란으로 둔다 */ ,CASE WHEN NVL(C.BASE_PRICE, 0) = 0 THEN NULL ELSE TO_CHAR(ROUND((C.BASE_PRICE - P.BUY_PRICE) / C.BASE_PRICE * 100, 2), 'FM9999990.00') || '%' END AS BASE_MARGIN /* 기준가매익율(%) */ ,(SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M183' AND MD.CODE = C.BASE_PRICE_TYPE) AS BASE_PRICE_TYPE /* 기준가유형 */ ,'' AS TYPE_MARGIN /* 유형별 매익율 - 산출 출처 미정이라 보류 */ ,NVL((SELECT 'Y' FROM CMSPRICE_HST H WHERE H.CMS_CATLG_ID = P.CMS_CATLG_ID AND H.CATLG_SEQ = P.CATLG_SEQ AND ROWNUM = 1), 'N') AS HISTORY /* 변경이력 유무 (PK 선두라 인덱스로 끝난다) */ ,P.ADD_DATE /* 구매정보 등록일 */ ,P.CHANGE_DATE AS CHANGE_DATE /* 최종변경일 */ /* 불가 변경사유 : 공급상태가 불가인 행에서만 노출 (상품정보 목록의 [미사용 변경사유]와 같은 관례) */ ,CASE WHEN P.STATUS = 'D' THEN (SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M185' AND MD.CODE = P.SUPPLY_REASON_CODE) ELSE '' END AS UNAVAIL_REASON /* 불가 변경사유 */ /* 대체코드는 상품정보에만 있다(CMSCATLG.ALT_CATLG_ID). 사유가 중복존재(DUP)일 때만 노출 */ ,CASE WHEN P.STATUS = 'D' AND P.SUPPLY_REASON_CODE = 'DUP' THEN C.ALT_CATLG_ID ELSE '' END AS ALT_CODE /* 대체코드 */ /* -- 밴드4 : 거래조건 -- */ ,RTRIM(TO_CHAR(P.BUY_PRICE, 'FM999,999,999,990.99999'), '.') AS LIST_PRICE /* 매입단가(VAT별도) */ ,P.MIN_ORDER_QTY AS MOQ /* 최소주문수량 */ ,P.PUR_UNIT_QTY AS PUR_UNIT_QTY /* 주문배수수량 */ ,(SELECT MD.TEXT2 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M034' AND MD.CODE = P.PROCESS_TYPE) AS PROCESS_TYPE /* 거래유형 (M034 는 TEXT2 가 국문) */ ,(SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M186' AND MD.CODE = P.DELIVERY_TYPE) AS DELIVERY_TYPE /* 배송유형 */ /* 입고TR : 저장은 센터 회사코드다. 화면엔 센터명으로 보여야 하므로 W001(TEXT1=코드 / TEXT2=명 / TEXT4=B 구매사측)에서 되찾는다. 목록에 없는 코드는 코드 그대로 남긴다 - 빈칸이면 값이 있는지조차 안 보인다. */ ,NVL((SELECT MAX(MD.TEXT2) FROM ICOMCOD1 MD WHERE MD.TYPE = 'W001' AND MD.TEXT4 = 'B' AND MD.TEXT1 = P.WAREHOUSE_CODE) , P.WAREHOUSE_CODE) AS TR_NAME /* 입고TR(센터명) */ ,P.DELIVERY_LT AS LEADTIME /* 배송일수 */ ,(SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'M132' AND MD.CODE = P.ITEM_MAKE_TYPE) AS ITEM_TYPE /* 품목구분 */ ,(SELECT MD.TEXT1 FROM ICOMCOD1 MD WHERE MD.TYPE = 'TX17' AND MD.CODE = P.TAX_TYPE) AS TAX_TYPE /* 과세구분 */ ,P.SELLER_ITEM_NO AS SELLER_ITEM_NO /* 협력사품목코드 */ ,P.BUY_OPEN_DATE AS BUY_OPEN_DATE /* 매입단가 시작일 */ FROM CMSPRICE P, CMSCATLG C WHERE P.CMS_CATLG_ID = C.CMS_CATLG_ID
AND P.CMS_CATLG_ID IN
UPPER(#{item})
AND UPPER(P.CMS_CATLG_ID) LIKE UPPER(#{st_catlg_id}) || '%'
AND NVL(P.STATUS, 'C') != 'D'
AND P.STATUS = 'D'
AND P.BUY_CLOSE_DATE IS NOT NULL AND P.BUY_CLOSE_DATE < TO_CHAR(SYSDATE, 'YYYYMMDD')
AND P.BUY_CLOSE_DATE IS NOT NULL AND P.BUY_CLOSE_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND P.BUY_CLOSE_DATE <= TO_CHAR(SYSDATE + 30, 'YYYYMMDD')
AND (P.BUY_CLOSE_DATE IS NULL OR TRIM(P.BUY_CLOSE_DATE) IS NULL)
AND EXISTS (SELECT 1 FROM CMSCATEG CG WHERE CG.CMS_CATEG_ID = C.CMS_CATEG_ID AND CG.STATUS != 'D' AND CG.SG_ID IN
#{item}
)
AND C.CMS_CATEG_ID IN
#{item}
AND P.PROCESS_TYPE = #{st_process_type}
AND P.DELIVERY_TYPE = #{st_delivery_type}
AND C.DESCRIPTION_LOC LIKE '%' || #{st_item_name} || '%'
AND C.SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND C.MODEL_INFO LIKE '%' || #{st_model_info} || '%'
AND C.MAKER_CODE = #{st_maker_code}
AND P.AGENT IN
#{item}
AND EXISTS (SELECT 1 FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = P.AGENT AND CMPY.COM_NAME_LOC LIKE '%' || #{st_agent_name} || '%')
AND EXISTS (SELECT 1 FROM CMSCATEG CG, ICOMCOD3 MD WHERE CG.CMS_CATEG_ID = C.CMS_CATEG_ID AND CG.STATUS != 'D' AND MD.BUYER = 'KRKORE0001' AND MD.TYPE = 'CMSM' AND MD.CODE2 = '1' AND MD.FLAG = 'Y' AND MD.CODE1 = CG.SG_ID AND MD.TEXT1 = #{st_kep_user_no})
AND P.CHANGE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND P.BUY_CLOSE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND P.ADD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
ORDER BY P.CMS_CATLG_ID, P.CATLG_SEQ

mapper.update:

/*insertMasterMdCmCmsBuyInfoPriceReqHd*/
INSERT INTO KEPMGPHD (
   BUYER, PM_NO, STATUS, REG_DATE, CHANGE_DATE
 , REG_USER_ID, REG_USER_DEPT, GUBUN, CA_FLAG, SUBJECT, REMARK
) VALUES (
   #{st_com_code}, #{st_pm_no}, 'C', SYSDATE, SYSDATE
 , #{st_user_id}, #{st_user_dept}, #{st_gubun}, 'N', #{st_subject}, #{st_remark}
)


/*insertMasterMdCmCmsBuyInfoPriceReqDt*/
INSERT INTO KEPMGPDT (
   BUYER, PM_NO, PM_SEQ, STATUS, REG_DATE, CHANGE_DATE, REG_USER_ID
 , CMS_CATLG_ID, CATLG_SEQ, AGENT
 , RE_LIST_PRICE, CH_LIST_PRICE
 , BELOW_TEXT
) VALUES (
   #{st_com_code}, #{st_pm_no}, #{st_pm_seq}, 'C', SYSDATE, SYSDATE, #{st_user_id}
 , SUBSTR(#{BUY_INFO_ID}, 1, INSTR(#{BUY_INFO_ID}, '-') - 1)
 , TO_NUMBER(SUBSTR(#{BUY_INFO_ID}, INSTR(#{BUY_INFO_ID}, '-') + 1))
 , #{AGENT}
 , (SELECT P.BUY_PRICE FROM CMSPRICE P
     WHERE P.CMS_CATLG_ID = SUBSTR(#{BUY_INFO_ID}, 1, INSTR(#{BUY_INFO_ID}, '-') - 1)
       AND P.CATLG_SEQ    = TO_NUMBER(SUBSTR(#{BUY_INFO_ID}, INSTR(#{BUY_INFO_ID}, '-') + 1)))
 , TO_NUMBER(NULLIF(#{PRICE_AFTER},  ''))
 , #{PRICE_REASON}
)
